  id: x.id,
  novoStatus: x.novoStatus,
  // Se o novo status é "Concluído", foi a leitura final; senão, foi a pré-leitura.
  estagio: /conclu/i.test(x.novoStatus) ? 'final' : 'pre',
  feitaPor
}));

return [{ json: { ...item, analisesParaAtualizar, limparPendencia: true,
  textoResposta: `✅ Concluído:\n\n${p.resumo}\n\nLeitura feita por: ${feitaPor}` } }];

const principal = $('Interpretar comando').first().json;
const raw = $input.first().json;

if (raw?.error) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: '',
    textoResposta: '⚠️ A IA está indisponível no momento. Tente de novo em alguns instantes ou use o formato do comando.'
  }}];
}

let texto = raw?.content?.parts?.[0]?.text ?? '';
texto = String(texto).replace(/```json|```/g, '').trim();

let ia;
try { ia = JSON.parse(texto); } catch (e) { ia = { intencao: 'desconhecido' }; }

const tanques = Array.isArray(ia.tanques)
  ? ia.tanques.map(t => String(t).trim().toUpperCase()).filter(Boolean)
  : [];
const dataOk = /^\d{2}\/\d{2}\/\d{4}$/.test(ia.data || '');

// Consultas: só leem a planilha, então executam direto, sem pedir "sim"
const CONSULTAS = {
  consulta_drops: 'drops para hoje',
  consulta_analises_terra: 'Quais analises de tanques terra saem hoje?',
  consulta_analises_navio: 'Quais analises de tanques navio saem hoje?',
  consulta_bags: 'Quais bags posso descartar hoje',
  consulta_potes: 'Quais potes do navio posso descartar hoje'
};

if (CONSULTAS[ia.intencao]) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: CONSULTAS[ia.intencao],
    textoResposta: ''
  }}];
}

let comando = null, erro = null, leituraCmd = null;
const tipoIA = String(ia.tipo || '').toLowerCase();
const tipoOk = tipoIA === 'terra' || tipoIA === 'navio';
const navioIA = (tipoIA === 'navio' && ia.navio) ? ' ' + String(ia.navio).trim() : '';

const ESCRITAS = ['coleta_terra', 'coleta_navio', 'registro_analise', 'concluir_drops', 'concluir_leitura'];
const nivel = principal.nivelAtual;

if (nivel === 'Consultor' && (ESCRITAS.includes(ia.intencao) || ia.intencao === 'gerenciar_cargo')) {
  erro = 'Consultores têm acesso somente de consulta. Peça a um administrador para registrar isso.';
} else if (ia.intencao === 'gerenciar_cargo' && nivel && nivel !== 'Admin') {
  erro = 'Só administradores podem alterar cargos de usuários.';
} else if (ia.intencao === 'gerenciar_cargo') {
  // O cargo e o telefone precisam estar escritos na mensagem original: a IA não pode inventar nem "consertar"
  const msg = String(principal.mensagem_original || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const mencionados = new Set();
  if (/\badmin(istrador)?\b/.test(msg)) mencionados.add('Admin');
  if (/\boperador\b/.test(msg)) mencionados.add('Operador');
  if (/\bconsultor\b/.test(msg)) mencionados.add('Consultor');
  const cargo = { admin: 'Admin', administrador: 'Admin', operador: 'Operador', consultor: 'Consultor' }[String(ia.cargo || '').trim().toLowerCase()];
  const telDigitado = String(ia.telefone || '').replace(/\D/g, '');
  let tel = telDigitado;
  if (/^\d{10,11}$/.test(tel)) tel = '55' + tel;
  const nome = ia.nome ? String(ia.nome).replace(/\s+/g, ' ').trim() : '';
  if (!cargo || !mencionados.has(cargo)) erro = 'Cargo inválido. Use Admin, Operador ou Consultor.';
  else if (!/^\d{12,13}$/.test(tel) || !msg.replace(/\D/g, '').includes(telDigitado)) erro = 'Não identifiquei o número do usuário com DDD (ex: 55 + DDD + número).';
  else comando = `trocar cargo de ${cargo} para o número ${tel}${nome ? ' nome ' + nome : ''}`;
} else if (ia.intencao === 'coleta_terra') {
  if (!tanques.length || !tanques.every(t => /^\d+$/.test(t))) erro = 'Não identifiquei os tanques de terra.';
  else if (tanques.length > 8) erro = 'Limite de 8 tanques de terra por mensagem.';
  else if (!dataOk) erro = 'Faltou a data da coleta (dd/mm/aaaa).';
  else comando = `registrar coleta tanque terra ${tanques.join(',')} data ${ia.data}`;
} else if (ia.intencao === 'coleta_navio') {
  if (!ia.navio) erro = 'Faltou o nome do navio com a viagem (ex: O.SKY 123).';
  else if (!tanques.length || !tanques.every(t => /^\d+[CPSAF]?$/.test(t))) erro = 'Não identifiquei os tanques do navio.';
  else if (tanques.length > 16) erro = 'Limite de 16 tanques de navio por mensagem.';
  else if (!dataOk) erro = 'Faltou a data da coleta (dd/mm/aaaa).';
  else comando = `Coleta navio ${String(ia.navio).trim()} tanques ${tanques.join(',')} data ${ia.data}`;
} else if (ia.intencao === 'registro_analise') {
  const analise = String(ia.analise || '').toLowerCase();
  const ehNavio = !!ia.navio;
  const limite = ehNavio ? 16 : 8;
  const tanqueOk = ehNavio ? /^\d+[CPSAF]?$/ : /^\d+$/;
  if (!['normal', 'stress'].includes(analise)) erro = 'Faltou dizer se a análise é normal ou stress.';
  else if (!tanques.length || !tanques.every(t => tanqueOk.test(t))) erro = 'Não identifiquei os tanques da análise.';
  else if (tanques.length > limite) erro = `Limite de ${limite} tanques por mensagem.`;
  else if (!dataOk) erro = 'Faltou a data da análise (dd/mm/aaaa).';
  else comando = `Analise ${analise} tanques ${tanques.join(',')}${ehNavio ? ' navio ' + String(ia.navio).trim() : ''} data ${ia.data}`;
} else if (ia.intencao === 'concluir_drops') {
  const dia = String(ia.dia || '').toUpperCase();
  if (!tipoOk) erro = 'Não deu para saber se os drops são de terra ou de navio.';
  else if (dia && !['D5', 'D10', 'D15'].includes(dia)) erro = 'Dia de drop inválido. Use D5, D10 ou D15.';
  else comando = `Concluir drops ${dia ? dia + ' ' : ''}${tipoIA}${navioIA}`;
} else if (ia.intencao === 'concluir_leitura') {
  const fase = String(ia.fase || '').toLowerCase();
  const leitura = String(ia.leitura || '').toUpperCase();
  const analise = String(ia.analise || '').toLowerCase();
  if (!tipoOk) erro = 'Não deu para saber se a leitura é de terra ou de navio.';
  else if (fase && !['pre', 'final'].includes(fase)) erro = 'Fase inválida. Use pre ou final.';
  else if (leitura && !['CT', 'BL', 'WORT'].includes(leitura)) erro = 'Leitura inválida. Use CT, BL ou WORT.';
  else if (analise && !['normal', 'stress'].includes(analise)) erro = 'Análise inválida. Use normal ou stress.';
  else leituraCmd = `Concluir ${fase ? fase + ' ' : ''}leitura ${leitura ? leitura + ' ' : ''}${analise ? analise + ' ' : ''}${tipoIA}${navioIA}`;
} else {
  erro = 'Comando inválido. Se desejar consultar a lista de comandos, escreva o que procura. Por exemplo: *consultar drops*\n\n' +
    'Opções: drops, tanques, análises, leituras, descarte, cargos.';
}

// Concluir leitura já lista e pede "sim" no fluxo normal: não pede confirmação duas vezes
if (leituraCmd) {
  return [{ json: {
    numero: principal.numero,
    nomeContato: principal.nomeContato,
    comando_ia: null,
    reenviarComando: leituraCmd,
    textoResposta: ''
  }}];
}

const criadoEm = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{ json: {
  numero: principal.numero,
  nomeContato: principal.nomeContato,
  comando_ia: comando,
  reenviarComando: '',
  idsCSV: 'IA',
  novosStatusCSV: 'IA',
  resumo: comando,
  criadoEm,
  textoResposta: comando
    ? `🤖 Entendi:\n${comando}\n\nResponda *sim* para confirmar ou *não* para cancelar.`
    : `❌ ${erro}`
}}];

